const clamp = (n,a,b) => Math.max(a,Math.min(b,n));
const dbGain = db => db <= -60 ? 0 : Math.pow(10,db/20);
const formatTime = (seconds,ms=false) => { const n=Math.max(0,Math.round(seconds*1000)); return `${String(Math.floor(n/60000)).padStart(2,'0')}:${String(Math.floor(n/1000)%60).padStart(2,'0')}${ms?'.'+String(n%1000).padStart(3,'0'):''}`; };
const makeTrack = (name,index=0) => ({id:id(),name,color:COLORS[index%COLORS.length],volume:0,pan:0,mute:false,solo:false,armed:false,eq:{low:0,mid:0,high:0},compressor:false,clips:[]});
const makeProject = () => {const tracks=['Voz principal','Música','Efectos'].map(makeTrack);tracks[0].armed=true;return {version:1,name:'Mi sesión',tracks,master:0,region:null};};
const makeClip = (source,name,duration,start=0) => ({id:id(),source,name,start,offset:0,duration,gain:0,fadeIn:0,fadeOut:0,points:[],volumePoints:[]});
const projectDuration = p => Math.max(0,...p.tracks.flatMap(t=>t.clips.map(c=>c.start+c.duration)));
const findClip = (p,cid) => { for(const track of p.tracks){const clip=track.clips.find(c=>c.id===cid);if(clip)return {track,clip};}return null; };
const audible = (track,project) => !track.mute && (!project.tracks.some(t=>t.solo)||track.solo);
