function fades(clip){let fi=clamp(clip.fadeIn,0,clip.duration),fo=clamp(clip.fadeOut,0,clip.duration);if(fi+fo>clip.duration){const f=clip.duration/(fi+fo);fi*=f;fo*=f;}return [fi,fo];}
