function addVolumePoint(project,cid,time){const found=findClip(project,cid);if(!found)return null;const c=found.clip,t=clamp(time-c.start,0,c.duration);if(!c.volumePoints?.length)c.volumePoints=[{time:0,gain:1},{time:c.duration,gain:1}];const existing=c.volumePoints.find(p=>Math.abs(p.time-t)<.003);if(existing)return existing;const point={time:t,gain:volumeEnvelope(c,t)};c.volumePoints.push(point);c.volumePoints.sort((a,b)=>a.time-b.time);return point;}
function removeVolumePoint(project,cid,time){const found=findClip(project,cid);if(!found)return false;const points=found.clip.volumePoints||[],before=points.length;found.clip.volumePoints=points.filter(p=>Math.abs(p.time-time)>.003);return found.clip.volumePoints.length!==before;}
function splitClip(project,cid,time){const found=findClip(project,cid);if(!found)return null;const {track,clip}=found;const elapsed=time-clip.start;if(elapsed<.005||elapsed>clip.duration-.005)return null;const right={...clip,id:id(),start:time,offset:clip.offset+elapsed,duration:clip.duration-elapsed,fadeIn:0,volumePoints:sliceVolumePoints(clip,elapsed,clip.duration),points:(clip.points||[]).filter(p=>p>elapsed+.001).map(p=>p-elapsed)};right.fadeOut=Math.min(clip.fadeOut,right.duration);clip.points=(clip.points||[]).filter(p=>p<elapsed-.001);clip.volumePoints=sliceVolumePoints(clip,0,elapsed);clip.duration=elapsed;clip.fadeOut=0;clip.fadeIn=Math.min(clip.fadeIn,elapsed);track.clips.splice(track.clips.indexOf(clip)+1,0,right);return right;}
