function duplicateClip(project,cid,position){const f=findClip(project,cid);if(!f)return null;const copy={...f.clip,id:id(),start:position??f.clip.start+f.clip.duration,points:[...(f.clip.points||[])],volumePoints:(f.clip.volumePoints||[]).map(p=>({...p}))};f.track.clips.push(copy);return copy;}
function addClipPoint(project,cid,time){const found=findClip(project,cid);if(!found)return null;const c=found.clip,relative=time-c.start;if(relative<=.005||relative>=c.duration-.005)return null;c.points=c.points||[];if(c.points.some(p=>Math.abs(p-relative)<.003))return null;c.points.push(relative);c.points.sort((a,b)=>a-b);return relative;}
function removeClipPoint(project,cid,point){const found=findClip(project,cid);if(!found)return false;const before=(found.clip.points||[]).length;found.clip.points=(found.clip.points||[]).filter(p=>Math.abs(p-point)>.003);return found.clip.points.length!==before;}
